    capacity = get_value(instance, "capacity", "vehicle_capacity", "cap", default=0)
    try:
        capacity = float(capacity)
    except Exception:
        capacity = 0.0

    def xy(i):
        if coords is None:
            return (0.0, 0.0)
        if isinstance(coords, dict):
            v = coords.get(i, (0.0, 0.0))
            return (v[0], v[1])
        if 0 <= i < len(coords):
            v = coords[i]
            return (v[0], v[1])
        return (0.0, 0.0)

    def dem(i):
        if demand is None:
            return 0.0
        if isinstance(demand, dict):
            return float(demand.get(i, 0.0))
        if 0 <= i < len(demand):
            return float(demand[i])
        return 0.0

    if isinstance(demand, dict):
        ids = [k for k in demand.keys() if k != 0]
    elif demand is not None:
        ids = list(range(1, len(demand)))
    elif isinstance(coords, dict):
        ids = [k for k in coords.keys() if k != 0]
    elif coords is not None:
        ids = list(range(1, len(coords)))
    else:
        ids = to_list(get_value(instance, "customers", default=[]))
        ids = [i for i in ids if i != 0]

    ids = sorted(ids)
    if not ids:
        return []

    if capacity <= 0:
        return [[i] for i in ids]

    depot = 0
    dx, dy = xy(depot)

    def dist(i, j):
        xi, yi = xy(i)
        xj, yj = xy(j)
        a = xi - xj
        b = yi - yj
        return (a * a + b * b) ** 0.5

    def angle_key(i):
        x, y = xy(i)
        return ((y - dy) / (abs(x - dx) + abs(y - dy) + 1e-12), dist(depot, i), -dem(i), i)

    customers = sorted(ids, key=angle_key)

    routes = []
    cur = []
    load = 0.0
    for c in customers:
        d = dem(c)
        if cur and load + d > capacity:
            routes.append(cur)
            cur = [c]
            load = d
        else:
            cur.append(c)
            load += d
    if cur:
        routes.append(cur)

    def route_load(r):
        s = 0.0
        for c in r:
            s += dem(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        cost = dist(depot, r[0])
        for a, b in zip(r, r[1:]):
            cost += dist(a, b)
        cost += dist(r[-1], depot)
        return cost

    def improve_route(r):
        n = len(r)
        if n < 4:
            return r
        improved = True
        while improved:
            improved = False
            best_delta = 0.0
            best_i = -1
            best_j = -1
            for i in range(n - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 1, n - 1):
                    c = r[j]
                    d = depot if j == n - 1 else r[j + 1]
                    delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                    if delta < best_delta:
                        best_delta = delta
                        best_i = i
                        best_j = j
            if best_i >= 0:
                r = r[:best_i] + r[best_i:best_j + 1][::-1] + r[best_j + 1:]
                n = len(r)
                improved = True
        return r

    routes = [improve_route(r) for r in routes]

    def merge_once(routes):
        m = len(routes)
        best_gain = 1e-12
        best = None
        for i in range(m):
            ri = routes[i]
            li = route_load(ri)
            ci = route_cost(ri)
            for j in range(i + 1, m):
                rj = routes[j]
                if li + route_load(rj) > capacity:
                    continue
                rev_i = ri[::-1]
                rev_j = rj[::-1]
                candidates = [
                    ri + rj,
                    ri + rev_j,
                    rev_i + rj,
                    rev_i + rev_j,
                ]
                for cand in candidates:
                    gain = ci + route_cost(rj) - route_cost(cand)
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, j, cand)
        if best is None:
            return False, routes
        i, j, cand = best
        new_routes = []
        for idx, r in enumerate(routes):
            if idx == i:
                new_routes.append(cand)
            elif idx != j:
                new_routes.append(r)
        return True, new_routes

    def relocate_once(routes):
        m = len(routes)
        for i in range(m):
            ri = routes[i]
            if len(ri) <= 1:
                continue
            for pos, c in enumerate(ri):
                dc = dem(c)
                base_ri = ri[:pos] + ri[pos + 1:]
                for j in range(m):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load(rj) + dc > capacity:
                        continue
                    best_pos = None
                    best_cost = route_cost(rj)
                    for k in range(len(rj) + 1):
                        cand = rj[:k] + [c] + rj[k:]
                        cc = route_cost(cand)
                        if cc + 1e-12 < best_cost:
                            best_cost = cc
                            best_pos = k
                    if best_pos is not None:
                        new_rj = rj[:best_pos] + [c] + rj[best_pos:]
                        new_routes = []
                        for idx, r in enumerate(routes):
                            if idx == i:
                                if base_ri:
                                    new_routes.append(base_ri)
                            elif idx == j:
                                new_routes.append(new_rj)
                            else:
                                new_routes.append(r)
                        return True, new_routes
        return False, routes

    guard = 0
    changed = True
    while changed and guard < 200:
        guard += 1
        changed = False
        for idx in range(len(routes)):
            routes[idx] = improve_route(routes[idx])
        ok, new_routes = merge_once(routes)
        if ok:
            routes = new_routes
            changed = True
            continue
        ok, new_routes = relocate_once(routes)
        if ok:
            routes = new_routes
            changed = True

    seen = set()
    final_routes = []
    for r in routes:
        rr = []
        load = 0.0
        for c in r:
            if c not in seen and load + dem(c) <= capacity:
                rr.append(c)
                seen.add(c)
                load += dem(c)
        if rr:
            final_routes.append(rr)

    for c in ids:
        if c not in seen:
            placed = False
            for r in final_routes:
                if route_load(r) + dem(c) <= capacity:
                    r.append(c)
                    seen.add(c)
                    placed = True
                    break
            if not placed:
                final_routes.append([c])
                seen.add(c)

    return final_routes
